    lines = served_text.split("\n")
    if not lines or not is_header_line(lines[0].rstrip("\r")):
        return [], served_text
    for i, line in enumerate(lines):
        if not line.strip():
            return lines[:i], "\n".join(lines[i + 1:])
    return lines, ""


def _header(lines: list[str], name: str) -> str | None:
    prefix = name + ":"
